static async Task PreloadMonitorSmoke() {
    var cell=Fixture.Cells[0];
    var observations=new List<Observation>();
    var errors=new List<object>();
    var smoke=new Dictionary<string,object?> {
        ["status"]="running", ["accepted"]=false, ["start_ns"]=Ns(),
        ["scope"]="new_empty_100_column_fixture_before_first_insert",
        ["before_load"]=false, ["open_session_release_verified"]=false,
        ["session_disposed_release_verified"]=false, ["admin_disposed_release_verified"]=false,
        ["sql"]=ObserveSql, ["observations"]=observations, ["errors"]=errors
    };
    Probe["preload_monitor_smoke"]=smoke; Persist();
    using var session=Connection(); using var admin=Connection();
    Identity? id=null,adminId=null;
    try {
        Require(Receipts.Count==0,"preload smoke must precede every fixture INSERT");
        smoke["before_load"]=true;
        await Open(session,Total.Token);
        id=await Guard(session,"preload-smoke-session",cell);
        smoke["session_identity"]=id;
        await Open(admin,Total.Token);
        adminId=await Guard(admin,"preload-smoke-admin",cell);
        smoke["admin_identity"]=adminId;
        Require(id.Spid!=adminId.Spid && id.ConnectionId!=adminId.ConnectionId,
            "preload smoke requires independent dedicated connections");
        var seen=await Observe(admin,id,cell,Total.Token); observations.Add(seen);
        Require(seen.Sets[0].Count==1 && seen.Sets[0][0]["connection_id"] is Guid physical &&
            physical==id.ConnectionId && Idle(seen,false),
            "preload monitor did not identify the idle live session");
        await Guard(session,"preload-smoke-immutable-identity",cell,id);
        await Release(id,cell,false,"preload-smoke-open-session");
        smoke["open_session_release_verified"]=true;
    } catch(Exception e) {
        errors.Add(new { phase="monitor_identity_idle",type=e.GetType().Name,e.Message });
    } finally {
        async Task Close(SqlConnection c,Identity? expected,string name,string flag) {
            try {
                await c.DisposeAsync().AsTask().WaitAsync(TimeSpan.FromSeconds(15));
                if(expected!=null) {
                    await Release(expected,cell,true,name);
                    smoke[flag]=true;
                }
            } catch(Exception e) {
                errors.Add(new { phase=name,type=e.GetType().Name,e.Message });
            }
        }
        await Close(session,id,"preload-smoke-session-after-dispose","session_disposed_release_verified");
        await Close(admin,adminId,"preload-smoke-admin-after-dispose","admin_disposed_release_verified");
        smoke["end_ns"]=Ns();
        smoke["status"]=errors.Count==0?"passed":"failed";
        smoke["accepted"]=errors.Count==0;
        Save("preload-monitor-smoke.json",smoke); Persist();
    }
    Require(errors.Count==0,"preload monitor/identity/release smoke failed; see preload-monitor-smoke.json");
}
